import { GoogleGenAI } from '@google/genai';
import { marked } from 'marked';
import React, { useState, useEffect, useRef } from 'react';
import { createRoot } from 'react-dom/client';

// NOTE: Using process.env.API_KEY as strictly required by guidelines.
// The previous code used GEMINI_API_KEY, but guidelines say process.env.API_KEY.
const API_KEY = process.env.API_KEY;

const JARVIS_CONTEXT = `
ARTIFACT: Jarvis Protocol - Gmail Optimization Strategy
OBJECTIVE: Mitigate Volume (The Waves) & Secure High-Priority Intelligence (The Glowing Cubes)

Class JarvisProtocol:
    def deploy_vertical_grid_lines(self):
        """
        Phase 1 & 2: Diverting the 'Waves' (System Notifications)
        Logic: Catch noise-producing bots and archive them into containment labels.
        """
        filters = {
            "Internal_Notifications": {
                "search_query": 'from:(*@asana.com OR jira@* OR *notify* OR *no-reply*) OR subject:("commented on" OR "shared a document")',
                "action": "Skip Inbox, Apply Label: 'Sys/Notifications'",
                "visual_ref": "Blue Light Ribbons (Dampened)"
            },
            "GitHub_Background_Flow": {
                "search_query": 'from:noreply@github.com -subject:("mention" OR "assigned" OR "requested your review")',
                "action": "Archive, Apply Label: 'Sys/GitHub-Flow'",
                "visual_ref": "Lower Grid Stabilization"
            }
        }
        return filters

    def illuminate_glowing_cubes(self):
        """
        Phase 3 & 4: Elevating the 'Signal' (VIPs & GitHub Mentions)
        Logic: Extract critical packets and force them to 'High Luminosity' (Priority Inbox).
        """
        priorities = {
            "VIP_Direct_Contact": {
                "criteria": "Defined Level 1 Stakeholders",
                "action": "Star, Mark as Important, Pin to 'Important & Unread'",
                "visual_ref": "Yellow/Gold Glowing Cubes"
            },
            "GitHub_Actionable": {
                "search_query": 'from:noreply@github.com subject:("mention" OR "assigned" OR "requested your review")',
                "action": "Star, Mark as Important, Apply Label: 'Priority/Action-Required'",
                "visual_ref": "Pink/High-Luminosity Cubes"
            }
        }
        return priorities

Visual Schematic: Data-scape Light Stream.
Audio Profile: Ambient Focus.
Current Status: Phase 1-4 Active.
`;

const INITIAL_PROMPT = "Generate the Command Summary for the final phase: 'The Blackout Filter' (automatically archiving everything that isn't from a human or a tracked project)";

function App() {
  const [input, setInput] = useState(INITIAL_PROMPT);
  const [messages, setMessages] = useState<{role: 'user' | 'ai', content: string}[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg = input;
    setMessages(prev => [...prev, { role: 'user', content: userMsg }]);
    setInput('');
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: API_KEY });

      // Using gemini-3-flash-preview as recommended for text tasks with reasoning.
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userMsg,
        config: {
          systemInstruction: `You are JARVIS, an advanced AI protocol assistant. \n${JARVIS_CONTEXT}\nYour task is to implement the requested protocols in Python or providing logical command summaries. Keep responses technical, concise, and aligned with the "Visual/Audio" aesthetic defined.`,
          tools: [{ codeExecution: {} }],
        },
      });

      const text = response.text;

      setMessages(prev => [...prev, { role: 'ai', content: text || 'Protocol Executed. No text output.' }]);
    } catch (error) {
      console.error(error);
      setMessages(prev => [...prev, { role: 'ai', content: `Error: ${error instanceof Error ? error.message : 'Unknown error'}` }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="jarvis-container">
      <header>
        <h1>Jarvis Protocol <span style={{fontSize: '0.6em', opacity: 0.7}}>// v1.0.alpha</span></h1>
        <div className="status-indicator">SYSTEM ONLINE</div>
      </header>

      <div className="chat-window">
        {messages.length === 0 && (
          <div className="message ai">
            <div dangerouslySetInnerHTML={{ __html: marked.parse(`**Protocol Artifact Loaded.**\n\nExisting Modules:\n- Vertical Grid Lines (Notification Filtering)\n- Glowing Cubes (VIP Prioritization)\n\nAwaiting directive for Phase 5: "The Blackout Filter".`) }} />
          </div>
        )}

        {messages.map((msg, idx) => (
          <div key={idx} className={`message ${msg.role}`}>
             <div dangerouslySetInnerHTML={{ __html: marked.parse(msg.content) }} />
          </div>
        ))}
        {isLoading && <div className="message ai"><i>Processing logic streams...</i></div>}
        <div ref={chatEndRef} />
      </div>

      <div className="input-area">
        <textarea 
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter' && !e.shiftKey) {
              e.preventDefault();
              handleSend();
            }
          }}
          placeholder="Enter command..."
          disabled={isLoading}
        />
        <button onClick={handleSend} disabled={isLoading || !input.trim()}>
          Deploy
        </button>
      </div>
    </div>
  );
}

const root = createRoot(document.getElementById('root')!);
root.render(<App />);
